<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,shallowRef} from 'vue';
import type {MaterialImportGovernanceContext} from '../types/material-import-governance';
import PageHeader from '../components/PageHeader.vue';
const props=defineProps<{context:MaterialImportGovernanceContext}>(),s=shallowRef(props.context.snapshot()),query=ref(''),category=ref('all');
let alive=true,stop:(()=>void)|undefined;
const rows=computed(()=>s.value.tasks.filter(row=>`${row.title} ${row.id}`.toLowerCase().includes(query.value.toLowerCase())&&(category.value==='all'||category.value===row.kind)));
const statusNames:Record<string,string>={WAITING_UPLOAD:'等待上传',UPLOADING:'传输中',PAUSED:'已暂停',MERGING:'服务端合并',VALIDATING:'服务端检查',SELECTING:'等待标签确认',QUEUED:'队列中',WAITING:'等待处理',RUNNING:'处理中',SUCCEEDED:'已完成',DONE:'已完成',FAILED:'失败',INTERRUPTED:'传输中断',CANCELLED:'已取消',UNKNOWN:'状态待核验'};
const entries=[{key:'library',title:'素材与使用证据',description:'按原筛选查看尺寸、方向、质量、标签及历史使用。'},{key:'clean',title:'清洗工作台',description:'明确选择范围并配置清洗；确认后开始清洗。'},{key:'clean-history',title:'清洗历史与失败',description:'查看原任务进度、结果、失败原因及恢复入口。'},{key:'manual',title:'人工标注',description:'进入原素材库选择图片，沿用 Annotorious 和正式保存。'},{key:'ai',title:'AI 标注创建',description:'配置 AI 标注任务；预测候选仍须人工审核。'},{key:'integrity',title:'完整性与安全删除',description:'原质量、重复及冲突治理；删除先预览计划与引用保护。'},{key:'negative',title:'负样本池',description:'复用算法、类别和成员准入规则。'},{key:'labels',title:'标签管理',description:'复用当前项目标签字典，不建立第二套分类。'}];
function dispose(){stop?.();stop=undefined;props.context.signal.removeEventListener('abort',dispose)}
onMounted(()=>{if(props.context.signal.aborted)return;stop=props.context.subscribe(value=>{if(alive&&!props.context.signal.aborted)s.value=value});props.context.signal.addEventListener('abort',dispose,{once:true})});
onBeforeUnmount(()=>{alive=false;dispose()});
</script>
<template><section class="material-import-governance" aria-label="素材接入与治理"><PageHeader title="素材接入与治理" eyebrow="数据中心 / 素材接入" description="图片与数据集上传、任务进度和后续处理。" badge="素材管理" @back="context.actions.navigate('manage')"/>
 <div class="import-options"><section><h2>上传图片</h2><p>多图选择、分批上传与结果确认。</p><el-button type="primary" :disabled="!s.capabilities.images" @click="context.actions.images()">选择图片上传</el-button></section><section><h2>导入 ZIP 数据集</h2><p>分片上传、暂停续传、标签映射与导入确认。</p><el-button :disabled="!s.capabilities.zip" @click="context.actions.zip()">选择 ZIP 导入</el-button></section><section><h2>上传后继续处理</h2><p>用户自主进入素材、清洗或标注，不自动执行后续处理。</p><el-button :disabled="!s.capabilities.confirmation" @click="context.actions.confirmation()">恢复上传确认</el-button><small v-if="s.confirmationAvailable">本项目有待处理的上传确认</small></section></div>
 <el-alert v-if="s.error" :title="s.error" type="error" :closable="false"/>
 <section class="upload-history" aria-label="上传任务与历史"><header><div><h2>上传任务与历史</h2><p>当前上传任务记录 {{ s.total }} 条；传输与入库进度分别记录。</p></div><el-button :disabled="s.busy" :loading="s.busy" @click="context.actions.refresh()">核验上传任务</el-button></header><div class="task-filters"><el-input v-model="query" aria-label="搜索上传任务" placeholder="文件名或任务 ID" clearable/><select v-model="category" aria-label="上传类型"><option value="all">全部类型</option><option value="zip">ZIP</option><option value="browser-upload">普通图片</option></select></div>
 <el-table :data="rows" row-key="id" max-height="560" empty-text="完整任务中心当前没有匹配记录；可选择文件或查看原工作台。"><el-table-column label="文件 / 任务" min-width="180"><template #default="{row}"><strong>{{ row.title||row.id }}</strong><small>{{ row.id }}</small><small>{{ row.kind }}</small></template></el-table-column><el-table-column label="状态与传输" min-width="160"><template #default="{row}"><el-tag type="info">{{ statusNames[row.status]||row.status||'未提供' }}</el-tag><progress v-if="row.progress!==null" :value="row.progress" max="100" :aria-label="row.title+'阶段进度'"/><small>{{ row.progress===null?'进度尚待核验':row.progress+'%（当前阶段）' }}</small><small>{{ row.stage||'阶段未提供' }}</small><small v-if="row.queuePosition!==null">原队列位置 {{ row.queuePosition }}</small></template></el-table-column><el-table-column label="诊断 / 时间" min-width="190"><template #default="{row}"><p>{{ row.detail||'未提供诊断' }}</p><small>{{ row.verificationReason }}</small><small>{{ row.updatedAt||row.createdAt||'时间未提供' }}</small></template></el-table-column><el-table-column label="操作" min-width="170"><template #default="{row}"><div class="task-actions"><template v-if="row.kind==='zip'"><el-button link @click="context.actions.task(row.id,'open')">查看 ZIP 任务</el-button><el-button v-if="row.status==='UPLOADING'&&row.browserTransfer" link @click="context.actions.task(row.id,'pause')">暂停传输</el-button><el-button v-if="row.status==='PAUSED'||row.resumeRequired" link @click="context.actions.task(row.id,'resume')">重选原文件继续</el-button><el-button v-if="row.browserTransfer||row.localOnly||row.status==='PAUSED'" link type="danger" @click="context.actions.task(row.id,'cancel')">取消传输</el-button><el-button v-if="row.status==='UNKNOWN'" link @click="context.actions.task(row.id,'verify')">重新核验</el-button></template><el-button v-else link @click="context.actions.task(row.id,'open')">完整任务中心</el-button></div></template></el-table-column></el-table>
 <p v-if="s.truncated" class="history-note">仅展示前 100 条原记录；完整历史及恢复操作请使用完整任务中心。</p><p class="history-note">网络传输完成不代表解压、检查或入库完成；图片请求结果未知时不自动重传未确认批次。关闭上传视图与取消任务是不同操作。</p></section>
 <section class="governance" aria-label="可信素材治理入口"><header><h2>素材治理与后续工作</h2><p>按需要选择下一步，清洗和删除前需核对范围。</p></header><div class="governance-grid"><article v-for="entry in entries" :key="entry.key"><h3>{{ entry.title }}</h3><p>{{ entry.description }}</p><el-button @click="context.actions.navigate(entry.key)">进入{{ entry.title }}</el-button></article></div><p class="history-note">删除前须核对完整范围和历史引用；被训练、正式标注或历史快照引用的素材受到保护。</p></section>
</section></template>
<style scoped>.material-import-governance{min-width:0}.import-options{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:18px 0}.import-options section,.upload-history,.governance{background:white;border:1px solid var(--el-border-color-lighter,#ebeef5);border-radius:10px;padding:18px;min-width:0}.import-options h2,.upload-history h2,.governance h2{font-size:17px;margin:0 0 10px}.import-options p,.upload-history header p,.governance header p{font-size:13px;line-height:1.6;color:#687382;margin:0 0 14px}.import-options small{display:block;margin-top:9px;color:#687382}.upload-history{margin-bottom:18px}.upload-history>header{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.task-filters{display:flex;gap:10px;margin-bottom:14px}.task-filters :deep(.el-input){max-width:350px}.task-filters select{border:1px solid #dcdfe6;border-radius:5px;padding:6px 10px;background:white}.upload-history :deep(small){display:block;line-height:1.6;color:#687382;overflow-wrap:anywhere}.upload-history :deep(p){margin:6px 0;overflow-wrap:anywhere}.upload-history progress{display:block;width:100%;height:8px;margin:8px 0}.task-actions{display:flex;flex-direction:column;align-items:flex-start;gap:6px}.task-actions :deep(.el-button){margin:0}.history-note{font-size:12px;line-height:1.7;color:#687382;overflow-wrap:anywhere}.governance-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.governance-grid article{padding:14px;border:1px solid #e6e9ee;border-radius:8px;min-width:0}.governance-grid h3{font-size:14px;margin:0 0 8px}.governance-grid p{font-size:12px;line-height:1.7;color:#687382;min-height:42px}.governance-grid :deep(.el-button){max-width:100%;white-space:normal;height:auto;min-height:32px}@media(max-width:1000px){.import-options{grid-template-columns:repeat(2,minmax(0,1fr))}.governance-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.import-options,.governance-grid{grid-template-columns:minmax(0,1fr)}.upload-history,.governance,.import-options section{padding:12px}.upload-history>header{flex-wrap:wrap}.task-filters{flex-wrap:wrap}}</style>
